#!/usr/bin/env node
/**
 * legacy-cleanup-drop-settings.mjs — P3: legacy settings カラム削除 migration 生成
 *
 * 使用法:
 *   node scripts/legacy-cleanup-drop-settings.mjs
 *
 * 出力: supabase/migration_011_legacy_settings_cleanup.sql
 * 前提: admin が手動で byLocale array へ移行済であること
 */

const fs = require("fs")
const path = require("path")

const sql = `-- Migration 011: Drop legacy settings columns from paradigm.settings
-- Generated by scripts/legacy-cleanup-drop-settings.mjs
-- 冪等 (IF EXISTS) — 安全に実行可能
-- 前提: admin が手動で byLocale array へ移行済であること

DO $$ BEGIN
  ALTER TABLE paradigm.settings DROP COLUMN IF EXISTS analytics_umami_website_id;
  ALTER TABLE paradigm.settings DROP COLUMN IF EXISTS analytics_umami_website_id_en;
  ALTER TABLE paradigm.settings DROP COLUMN IF EXISTS calendar_url_ja;
  ALTER TABLE paradigm.settings DROP COLUMN IF EXISTS calendar_url_en;
END $$;
`

const outPath = path.join(__dirname, "..", "supabase", "migration_011_legacy_settings_cleanup.sql")
fs.writeFileSync(outPath, sql, "utf8")
console.log(`✓ Generated ${outPath}`)